 const transport=pathTransportNode({load,environmentScene,trace,hemisphere,ray},u,mediumOn);const indirect=T.Fn(([point,normal])=>{const total=T.vec3(0).toVar();T.Loop({start:0,end:16,type:'int',condition:'<',name:'geometrySample'},({geometrySample:i})=>{T.If(T.float(i).greaterThanEqual(u.geometry.w),()=>{T.Break();});const phase=T.float(i).mul(2.39996323).add(.392699),direction=hemisphere(normal,phase,T.float(i).add(.5).div(u.geometry.w)).toVar(),origin=point.add(normal.mul(u.geometryLimits.y.mul(2))).toVar(),throughput=T.vec3(1).toVar(),sum=T.vec3(0).toVar();T.Loop({start:0,end:4,type:'int',condition:'<',name:'geometryBounce'},({geometryBounce:b})=>{T.If(T.float(b).greaterThanEqual(u.geometry.z),()=>{T.Break();});const hit=trace(origin,direction,u.geometry.y);T.If(hit.z.lessThan(.5).or(hit.w.lessThan(.5)),()=>{T.Break();});const p=origin.add(direction.mul(hit.x)),base=u.geometryInfo.w.add(hit.y.mul(6)),normal=ray.normal(hit.y,p,direction.negate()),n=normal.dot(direction).greaterThan(0).select(normal.negate(),normal);sum.addAssign(throughput.mul(lighting(p,n,hit.y)));throughput.mulAssign(ray.field(hit.y,p,direction.negate(),1).xyz.mul(u.transport.y.greaterThan(.5).select(T.float(1).sub(ray.field(hit.y,p,direction.negate(),0).x),T.float(1))));origin.assign(p.add(n.mul(u.geometryLimits.y.mul(2))));direction.assign(hemisphere(n,phase.add(T.float(b).add(1).mul(1.618034)),T.float(.5)));});total.addAssign(sum);});return total.mul(T.float(Math.PI).div(u.geometry.w.max(1)));});return {...transport,indirect};
